schemas.schema-02-actors.prisma:
/// Registered user accounts with email/password credentials and
/// authentication metadata. Each user has a unique email address and
/// password hash stored using bcrypt. All personal data is isolated at user
/// level with strict privacy enforcement.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_users {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// User's email address for authentication and verification. Must be unique
  /// across all users.
  email String

  /// Password hash stored using bcrypt with work factor 12. Never stores
  /// plaintext passwords.
  password_hash String

  /// Timestamp when the user account was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the user account was last updated (password changes,
  /// profile updates, etc.).
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the user account was soft-deleted. Null means active
  /// account.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  sessions todo_user_sessions[]
  passwordResets todo_user_password_resets[]
  emailVerifications todo_user_email_verifications[]
  auditLogs todo_audit_logs[]
  todos todo_todos[]

  @@unique([email])
}

/// JWT session tokens with access/refresh support and token expiry
/// management. Tracks user login sessions for authentication lifecycle and
/// session validity. Associated with the user actor through foreign key
/// relationship.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_user_sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// User this session belongs to. {@link todo_users.id}.
  todo_user_id String @db.Uuid

  /// IP address where session was created.
  ip String

  /// Original URL from which session was created.
  href String

  /// Referrer URL for the session.
  referrer String

  /// Timestamp when session was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when session expires and is automatically invalidated.
  expired_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  user todo_users @relation(fields: [todo_user_id], references: [id], onDelete: Cascade)

  @@index([todo_user_id, created_at])
}

/// Records password reset tokens with 60-minute expiration and usage
/// tracking for user authentication flows. Handles secure token generation,
/// validation, and cleanup.
///
/// This table is managed through user authentication services without direct
/// user interaction, requiring:
/// - Unique token generation for each reset attempt
/// - 60-minute time-based expiration
/// - Usage tracking to prevent token reuse
/// - Secure storage of token values for verification
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_user_password_resets {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// User account associated with this password reset request. {@link
  /// todo_users.id}.
  todo_user_id String @db.Uuid

  /// Unique token string for password reset verification.
  token String

  /// Timestamp when token expires (60-minute validity).
  expires_at DateTime @db.Timestamptz

  /// Timestamp when token was successfully used to reset password.
  used_at DateTime? @db.Timestamptz

  /// Entry creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last modification timestamp.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  user todo_users @relation(fields: [todo_user_id], references: [id], onDelete: Cascade)

  @@index([todo_user_id])

  @@unique([token])
  @@index([expires_at])
}

/// Email verification tokens with 15-minute expiration for user account
/// verification. Stores unique tokens, target email, expiration timestamp,
/// and related to user account.
///
/// This is a subsidiary entity managed through the parent user account, not
/// requiring independent CRUD endpoints. The token is auto-generated,
/// unique, and expires after 15 minutes as required by authentication
/// process.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_user_email_verifications {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// User account associated with this email verification token. {@link
  /// todo_users.id}.
  todo_user_id String @db.Uuid

  /// Unique verification token for email confirmation. Generated as random
  /// string, stored hashed.
  token String

  /// Token expiration timestamp (15 minutes from creation). Required for
  /// security and session management.
  expires_at DateTime @db.Timestamptz

  /// Timestamp when the verification token was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the verification token was last modified.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the verification token was soft-deleted.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  user todo_users @relation(fields: [todo_user_id], references: [id], onDelete: Cascade)

  @@index([todo_user_id])

  @@unique([token])
}

schemas.schema-01-systematic.prisma:
/// System-wide configuration parameters including email templates, timeouts,
/// and feature flags. Manages application-wide settings like email
/// templates, expiration timeouts, and feature toggles.
///
/// This table stores all system-level parameters that affect application
/// behavior and user experience, including:
/// - Email verification timeout (15 minutes as per requirements)
/// - Password reset timeout (60 minutes as per requirements)
/// - Feature flags toggle for enabling/disabling features
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_system_configs {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Time in minutes for email verification links to expire (e.g., 15).
  email_verification_timeout Int @db.Integer

  /// Time in minutes for password reset tokens to expire (e.g., 60).
  password_reset_timeout Int @db.Integer

  /// Serialized JSON string of feature flags enabled for the application.
  feature_flags String

  /// Timestamp when the configuration record was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the configuration record was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the configuration record was soft-deleted. Nullable for
  /// soft delete handling.
  deleted_at DateTime? @db.Timestamptz
}

/// System-wide audit log entries tracking all system-level events including
/// user account changes and administrative actions.
///
/// Each audit entry records the event type, description, user context, and
/// timestamp for complete historical tracing of system activities.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_audit_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// User who performed the audit event. {@link todo_users.id}.
  todo_user_id String @db.Uuid

  /// Type of the audit event (e.g., 'user.created', 'account.deleted').
  event_type String

  /// Description of the audit event, with additional context if needed.
  event_description String?

  /// Timestamp when the audit log entry was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the audit log entry was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the audit log entry was soft-deleted (if applicable).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  user todo_users @relation(fields: [todo_user_id], references: [id], onDelete: Cascade)

  @@index([todo_user_id, created_at])
}

schemas.schema-03-todos.prisma:
/// Core todo items that users create, view, edit, and manage. Includes
/// required title, optional description, start date, due date, completion
/// status, and soft delete tracking. Each todo item belongs to a single user
/// account with strict user-data isolation enforced.
///
/// @namespace Todos
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_todos {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belongs to the user's account via {@link todo_users.id}.
  todo_user_id String @db.Uuid

  /// Title of the todo item. Minimum 1 character required.
  title String

  /// Optional description of the todo item.
  description String?

  /// Start date for the todo item.
  start_date DateTime? @db.Timestamptz

  /// Due date for completing the todo item.
  due_date DateTime? @db.Timestamptz

  /// Completion status. Defaults to false on creation.
  is_completed Boolean

  /// Timestamp of when the todo item was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp of the last update to the todo item.
  updated_at DateTime @db.Timestamptz

  /// Timestamp of soft deletion. Nullable for active items.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  user todo_users @relation(fields: [todo_user_id], references: [id], onDelete: Cascade)

  histories todo_histories[]

  @@index([todo_user_id])
}

/// Detailed record of all field modifications including timestamps, previous
/// values, and new values for each todo edit. Each history entry captures
/// atomic changes to title, description, start date, and due date fields
/// when a todo is modified.
///
/// @namespace Todos
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_histories {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Related todo item's ID.
  todo_id String @db.Uuid

  /// Timestamp when the edit was recorded.
  created_at DateTime @db.Timestamptz

  /// Timestamp of the last update to the history record (should match
  /// created_at for immutability).
  updated_at DateTime @db.Timestamptz

  /// Previous title value before edit. Null if title was not changed.
  prev_title String?

  /// New title value after edit. Null if title was not changed.
  new_title String?

  /// Previous description value before edit. Null if description was not
  /// changed.
  prev_description String?

  /// New description value after edit. Null if description was not changed.
  new_description String?

  /// Previous start date value before edit. Null if start date was not changed.
  prev_start_date DateTime? @db.Timestamptz

  /// New start date value after edit. Null if start date was not changed.
  new_start_date DateTime? @db.Timestamptz

  /// Previous due date value before edit. Null if due date was not changed.
  prev_due_date DateTime? @db.Timestamptz

  /// New due date value after edit. Null if due date was not changed.
  new_due_date DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  todo todo_todos @relation(fields: [todo_id], references: [id], onDelete: Cascade)

  @@index([todo_id, created_at])
}

schemas.schema-04-user-profile.prisma:
/// Stores user display names with maximum 20 character limit and no special
/// characters. Display names are required for user identification and must
/// comply with business rules regarding length and character usage.
///
/// @namespace UserProfile
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_profiles {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// User's display name shown to other users, must be between 1-20 characters
  /// with no special characters (alphabetic and numeric allowed).
  display_name String

  /// Timestamp when the profile was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the profile was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the profile was soft-deleted. Nullable for future soft
  /// delete implementation.
  deleted_at DateTime? @db.Timestamptz
}

