import { authorize_user_join } from "../../../authorize/authorize_user_join";
import { authorize_user_login } from "../../../authorize/authorize_user_login";
import { authorize_user_refresh } from "../../../authorize/authorize_user_refresh";

export async function test_api_user_registration_with_verification(
  connection: api.IConnection,
): Promise<void> {
  const email =
    RandomGenerator.name().toLowerCase().replace(/ /g, "") + "@company.com";
  const password = `${RandomGenerator.alphabets(4).toUpperCase()}${RandomGenerator.alphabets(3)}${RandomGenerator.pick(["!", "@", "#", "$", "%"])}`;
  const user = await authorize_user_join(connection, {
    body: {
      email,
      password,
    } satisfies ITodoUser.IJoin,
  });
  typia.assert(user);
  TestValidator.predicate(
    "user ID is valid UUID",
    /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(
      user.id,
    ),
  );
  TestValidator.equals("token response exists", user.token, user.token);
  TestValidator.predicate(
    "access token format",
    /^\w+\.\w+\.\w+$/.test(user.token.access),
  );
  TestValidator.predicate(
    "expired_at is valid date-time",
    /^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.\d{3}Z$/.test(
      user.token.expired_at,
    ),
  );
  TestValidator.predicate(
    "refreshable_until is valid date-time",
    /^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.\d{3}Z$/.test(
      user.token.refreshable_until,
    ),
  );
  TestValidator.predicate("password not returned", !("password" in user));
}

